/**
 * Build-time SEO prerender for the 280 A-domain content routes.
 *
 * Vite emits one SPA shell. This script copies that shell to each content route
 * and injects route-specific metadata so crawlers and link unfurlers do not see
 * 280 copies of the home-page metadata. The output is deterministic and is
 * regenerated by `pnpm build`; never edit dist/<slug>/index.html by hand.
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

// Paths resolve from the script location, not the process CWD, so calling this
// from another directory cannot silently prerender into the wrong repo.
const SCRIPT_DIR = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(SCRIPT_DIR, '..');
const DIST = join(ROOT, 'dist');
const SMOKE = join(ROOT, 'build', 'smoke-expectations.json');
const BASE_INDEX = join(DIST, 'index.html');
const SITE = 'https://www.temposoul.com';

